#[test]
fn issue_7292_actual_798_admitted_q20_correction_precedes_incidence_rejection() {
    let _lock = budget::GLOBAL_CAP_LOCK.lock().unwrap_or_else(|e| e.into_inner());
    let _element = budget::enter_element();
    budget::begin();
    let (host, source) = actual_first0();
    let band = NearBand::from_operands(&source, &host);
    let corners = crate::kernel::near_band::exact_vertex_set(&host);
    let faces: Vec<_> = host.iter().filter_map(|&t| Face::new(t, &band)).collect();
    let incidences = ExactFaceIncidences::new(&source, &host);
    let axes = SourceAxes::new(&source);
    let originals = [source[2][0], source[2][1]];
    let mut expected = Vec::new();
    for original in originals {
        let (d, selected) = selection::select(original, &faces, &band, &corners).unwrap();
        assert_eq!(selected.t, host[28]);
        let primary = exact_on_plane_weld(original, selected.t).unwrap();
        assert!(selected.admits(original, primary, d, &band, &corners));
        assert!(!incidences.admits(original, primary, &host));
        // The existing correction is independently valid: its original healthy
        // X-face support and selected plane both survive, without a new gate.
        let corrected = axes.candidate(original, primary, selected.t, &corners).unwrap();
        assert_eq!(corrected[0], original[0]);
        assert_eq!([corrected[1], corrected[2]], [primary[1], primary[2]]);
        assert!(selected.admits(original, corrected, d, &band, &corners));
        assert!(incidences.admits(original, corrected, &host));
        assert!(retains_finite_contacts(primary, corrected, &host));
        expected.push(corrected);
    }
    let mut actual = source;
    assert!(promote_cutter_verts_onto_host_faces(&mut actual, &host) > 0);
    for (original, corrected) in originals.into_iter().zip(expected) {
        for (before, after) in source.iter().flatten().zip(actual.iter().flatten()) {
            if vertex_bits(before) == vertex_bits(&original) {
                assert_eq!(vertex_bits(after), vertex_bits(&corrected),
                    "corrected admitted Q20 must survive original incidence rejection");
            }
        }
    }
    // The SIX other differing historical keys still fail primary drift. This
    // construction-order change must not reopen their refused-Q20 paths.
    for original in [source[4][0], source[4][1], source[4][2],
                     source[5][1], source[5][2], source[7][2]] {
        for (before, after) in source.iter().flatten().zip(actual.iter().flatten()) {
            if vertex_bits(before) == vertex_bits(&original) {
                assert_eq!(vertex_bits(after), vertex_bits(&original));
            }
        }
    }
    assert!(!budget::tripped());
}
